        public override string ToString()
        {
            var sb = new StringBuilder(100);
            var m = new NewOrderSingle();
            m.WrapForDecode(_buffer, _offset, _actingBlockLength, _actingVersion);
            m.BuildString(sb);
            return sb.ToString();
        }

        internal void BuildString(StringBuilder builder)
        {
            if (_buffer == null)
            {
                throw new ArgumentNullException("_buffer");
            }

            int originalLimit = this.Limit;
            this.Limit = _offset + _actingBlockLength;
            builder.Append("[NewOrderSingle](sbeTemplateId=");
            builder.Append(NewOrderSingle.TemplateId);
            builder.Append("|sbeSchemaId=");
            builder.Append(NewOrderSingle.SchemaId);
            builder.Append("|sbeSchemaVersion=");
            if (_parentMessage._actingVersion != NewOrderSingle.SchemaVersion)
            {
                builder.Append(_parentMessage._actingVersion);
                builder.Append('/');
            }
            builder.Append(NewOrderSingle.SchemaVersion);
            builder.Append("|sbeBlockLength=");
            if (_actingBlockLength != NewOrderSingle.BlockLength)
            {
                builder.Append(_actingBlockLength);
                builder.Append('/');
            }
            builder.Append(NewOrderSingle.BlockLength);
            builder.Append("):");

            builder.Append("PriceExponent=");
            builder.Append(this.PriceExponent);
            builder.Append('|');
            builder.Append("QtyExponent=");
            builder.Append(this.QtyExponent);
            builder.Append('|');
            builder.Append("OrderQty=");
            builder.Append(this.OrderQty);
            builder.Append('|');
            builder.Append("OrdType=");
            builder.Append(this.OrdType);
            builder.Append('|');
            builder.Append("ExecInst=");
            builder.Append(this.ExecInst);
            builder.Append('|');
            builder.Append("Price=");
            builder.Append(this.Price);
            builder.Append('|');
            builder.Append("TriggerType=");
            builder.Append(this.TriggerType);
            builder.Append('|');
            builder.Append("TriggerAction=");
            builder.Append(this.TriggerAction);
            builder.Append('|');
            builder.Append("TriggerPrice=");
            builder.Append(this.TriggerPrice);
            builder.Append('|');
